PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "nama" varchar not null, "email" varchar not null, "peran" varchar not null default 'penyetuju', "jabatan" varchar, "nomor_telepon" varchar, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "lokasi" ("id" integer primary key autoincrement not null, "kode_lokasi" varchar not null, "nama_lokasi" varchar not null, "tipe_lokasi" varchar check ("tipe_lokasi" in ('kantor_pusat', 'kantor_cabang', 'tambang')) not null default 'tambang', "alamat" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "drivers" ("id" integer primary key autoincrement not null, "nama_driver" varchar not null, "nomor_telepon" varchar not null, "nomor_sim" varchar not null, "jenis_sim" varchar check ("jenis_sim" in ('SIM A', 'SIM B1', 'SIM B2 Umum')) not null default 'SIM A', "status_driver" varchar check ("status_driver" in ('standby', 'bertugas')) not null default 'standby', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "kendaraan" ("id" integer primary key autoincrement not null, "nomor_polisi" varchar not null, "nomor_lambung" varchar not null, "merk_model" varchar not null, "jenis_kendaraan" varchar check ("jenis_kendaraan" in ('angkutan_orang', 'angkutan_barang')) not null default 'angkutan_orang', "kepemilikan" varchar check ("kepemilikan" in ('milik_perusahaan', 'sewa')) not null default 'milik_perusahaan', "nama_vendor_sewa" varchar, "biaya_sewa_bulanan" numeric, "lokasi_id" integer not null, "odometer_km" integer not null default '0', "kapasitas_tangki" integer not null default '60', "konsumsi_bbm_per_liter" numeric not null default '10', "tanggal_servis_terakhir" date, "tanggal_servis_berikutnya" date, "status_kendaraan" varchar check ("status_kendaraan" in ('tersedia', 'digunakan', 'perbaikan')) not null default 'tersedia', "created_at" datetime, "updated_at" datetime, foreign key("lokasi_id") references "lokasi"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "pemesanan" ("id" integer primary key autoincrement not null, "kode_pemesanan" varchar not null, "admin_id" integer not null, "nama_pemesan" varchar not null, "divisi_pemesan" varchar not null, "keperluan" text not null, "kendaraan_id" integer not null, "driver_id" integer not null, "lokasi_tujuan_id" integer not null, "tanggal_mulai" datetime not null, "tanggal_selesai" datetime not null, "status_pemesanan" varchar check ("status_pemesanan" in ('menunggu_level_1', 'menunggu_level_2', 'disetujui', 'ditolak', 'selesai')) not null default 'menunggu_level_1', "alasan_penolakan" text, "created_at" datetime, "updated_at" datetime, foreign key("admin_id") references "users"("id") on delete cascade, foreign key("kendaraan_id") references "kendaraan"("id") on delete cascade, foreign key("driver_id") references "drivers"("id") on delete cascade, foreign key("lokasi_tujuan_id") references "lokasi"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "persetujuan_pemesanan" ("id" integer primary key autoincrement not null, "pemesanan_id" integer not null, "penyetuju_id" integer not null, "level_persetujuan" integer not null, "status_persetujuan" varchar check ("status_persetujuan" in ('menunggu', 'disetujui', 'ditolak')) not null default 'menunggu', "catatan" text, "waktu_aksi" datetime, "created_at" datetime, "updated_at" datetime, foreign key("pemesanan_id") references "pemesanan"("id") on delete cascade, foreign key("penyetuju_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "log_bbm" ("id" integer primary key autoincrement not null, "pemesanan_id" integer, "kendaraan_id" integer not null, "jumlah_liter" numeric not null, "total_biaya" numeric not null, "odometer_awal" integer, "odometer_akhir" integer, "tanggal_isi" date not null, "created_at" datetime, "updated_at" datetime, foreign key("pemesanan_id") references "pemesanan"("id") on delete set null, foreign key("kendaraan_id") references "kendaraan"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "catatan_servis" ("id" integer primary key autoincrement not null, "kendaraan_id" integer not null, "tanggal_servis" date not null, "odometer_km" integer not null, "deskripsi_servis" text not null, "biaya" numeric not null default '0', "bengkel" varchar, "created_at" datetime, "updated_at" datetime, foreign key("kendaraan_id") references "kendaraan"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "log_aktivitas" ("id" integer primary key autoincrement not null, "pengguna_id" integer, "aksi" varchar not null, "deskripsi" text not null, "alamat_ip" varchar, "perangkat" text, "created_at" datetime, "updated_at" datetime, foreign key("pengguna_id") references "users"("id") on delete set null);
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "lokasi_kode_lokasi_unique" on "lokasi" ("kode_lokasi");
CREATE UNIQUE INDEX "kendaraan_nomor_polisi_unique" on "kendaraan" ("nomor_polisi");
CREATE UNIQUE INDEX "kendaraan_nomor_lambung_unique" on "kendaraan" ("nomor_lambung");
CREATE UNIQUE INDEX "pemesanan_kode_pemesanan_unique" on "pemesanan" ("kode_pemesanan");
PRAGMA writable_schema=OFF;
COMMIT;
